 java.util.concurrent.ExecutorService artwork=java.util.concurrent.Executors.newFixedThreadPool(2);final android.util.LruCache<String,android.graphics.Bitmap> covers=new android.util.LruCache<String,android.graphics.Bitmap>(8*1024*1024){protected int sizeOf(String k,android.graphics.Bitmap b){return b.getByteCount();}};final java.util.Set<String> requested=new java.util.HashSet<>();JSONArray games=new JSONArray();String console="All games",query="",pendingUri="",pendingName="";JSONObject selected;LinearLayout root,detail;GridView grid;ArrayList<JSONObject> visible=new ArrayList<>();BaseAdapter adapter;
