 public void onCreate(Bundle saved){super.onCreate(saved);getWindow().getDecorView().setSystemUiVisibility(5894);try{games=new JSONArray(getPreferences(0).getString("library","[]"));}catch(Exception ignored){}importSupplied();attachLocalPreviews();show();}
 void importSupplied(){try{java.io.File catalog=new java.io.File(getFilesDir(),"games/catalog.json");if(!catalog.isFile())return;String data=new String(java.nio.file.Files.readAllBytes(catalog.toPath()),java.nio.charset.StandardCharsets.UTF_8);String signature=Integer.toHexString(data.hashCode());if(signature.equals(getPreferences(0).getString("supplied_catalog_signature","")))return;JSONArray incoming=new JSONArray(data);for(int n=0;n<incoming.length();n++){JSONObject item=incoming.getJSONObject(n);String file=item.getString("file");Uri uri=Uri.parse("content://local.pitv.games/"+file);try(java.io.InputStream in=getContentResolver().openInputStream(uri)){}JSONObject existing=null;for(int i=0;i<games.length();i++){JSONObject old=games.getJSONObject(i);if(old.optString("title").equals(item.getString("title"))&&old.optString("console").equals(item.getString("console"))){existing=old;break;}}JSONObject game=existing==null?new JSONObject():existing;for(String key:new String[]{"id","title","console","year","description"})if(!item.optString(key).isEmpty())game.put(key,item.getString(key));game.put("uri",uri.toString());game.put("cover","content://local.pitv.games/"+item.getString("art"));if(existing==null)games.put(game);}java.util.ArrayList<JSONObject> sorted=new java.util.ArrayList<>();for(int i=0;i<games.length();i++)sorted.add(games.getJSONObject(i));java.util.Collections.sort(sorted,(a,b)->a.optString("title").compareToIgnoreCase(b.optString("title")));games=new JSONArray(sorted);save();getPreferences(0).edit().putString("supplied_catalog_signature",signature).apply();}catch(Exception ignored){}}
 void attachLocalPreviews(){boolean changed=false;for(int i=0;i<games.length();i++){JSONObject game=games.optJSONObject(i);if(game==null||!game.optString("id").matches("supplied-\\d+")||!game.optString("preview").isEmpty()||game.optBoolean("previewDisabled"))continue;String name="preview-"+game.optString("id").substring(9)+".mp4";java.io.File file=new java.io.File(getFilesDir(),"games/"+name);if(file.isFile()&&file.length()>1024)try{game.put("preview","content://local.pitv.games/"+name);changed=true;}catch(Exception ignored){}}if(changed)save();}
