 void addButton(LinearLayout parent,String label,Runnable action){Button b=TvStyle.button(this,label,action);b.setTextSize(14);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(32));lp.bottomMargin=dp(5);parent.addView(b,lp);consoleButtons.add(b);}
 void show(){consoleButtons.clear();if(retroAds!=null)retroAds.setRunning(false);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(18),dp(24),dp(18));root.setBackgroundColor(TvStyle.BG);setContentView(root);LinearLayout body=new LinearLayout(this);LinearLayout.LayoutParams bodyLp=new LinearLayout.LayoutParams(-1,0,1);bodyLp.topMargin=0;root.addView(body,bodyLp);LinearLayout rail=new LinearLayout(this);rail.setOrientation(1);LinearLayout.LayoutParams railLp=new LinearLayout.LayoutParams(dp(142),-1);railLp.rightMargin=dp(15);body.addView(rail,railLp);for(String name:new String[]{"All games","NES","SNES","Mega Drive / Genesis"})addButton(rail,consoleLabel(name),()->{console=name;filter();});retroAds=new RetroAdsView(this);LinearLayout.LayoutParams adLp=new LinearLayout.LayoutParams(-1,0,1);adLp.topMargin=dp(10);rail.addView(retroAds,adLp);LinearLayout catalog=new LinearLayout(this);catalog.setOrientation(1);body.addView(catalog,new LinearLayout.LayoutParams(0,-1,1.1f));grid=new GridView(this);grid.setNumColumns(3);grid.setHorizontalSpacing(dp(10));grid.setVerticalSpacing(dp(10));grid.setSelector(TvStyle.shape(this,0x00000000,0xff7eb4ff));grid.setDrawSelectorOnTop(true);catalog.addView(grid,new LinearLayout.LayoutParams(-1,0,1));detail=new LinearLayout(this);detail.setOrientation(1);detail.setPadding(dp(16),dp(14),dp(16),dp(14));detail.setBackground(TvStyle.shape(this,0xff182136,0xff303e57));LinearLayout.LayoutParams infoLp=new LinearLayout.LayoutParams(0,-1,1);infoLp.leftMargin=dp(16);body.addView(detail,infoLp);adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return visible.get(n).optString("id").hashCode();}public boolean hasStableIds(){return true;}public View getView(int n,View old,android.view.ViewGroup parent){JSONObject game=visible.get(n);LinearLayout card=new LinearLayout(GamesActivity.this);card.setOrientation(1);card.setPadding(dp(5),dp(5),dp(5),dp(7));card.setBackground(TvStyle.shape(GamesActivity.this,0xff26324a,0xff394763));ImageView cover=new ImageView(GamesActivity.this);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setBackgroundColor(0xff34415c);card.addView(cover,new LinearLayout.LayoutParams(-1,dp(122)));setCover(cover,game);TextView name=text(game.optString("title"),12);name.setMaxLines(2);name.setMinLines(2);card.addView(name);return card;}};grid.setAdapter(adapter);grid.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){gridPosition=index;JSONObject next=visible.get(index);if(selected==null||!next.optString("id").equals(selected.optString("id"))){selected=next;details();}}public void onNothingSelected(android.widget.AdapterView<?> p){}});grid.setOnItemClickListener((p,v,index,id)->{gridPosition=index;JSONObject next=visible.get(index);if(selected==null||!next.optString("id").equals(selected.optString("id"))){selected=next;details();}if(gamePlay!=null)gamePlay.requestFocus();});wireGameNavigation();filter();grid.requestFocus();}
 void filter(){visible.clear();for(int i=0;i<games.length();i++){JSONObject game=games.optJSONObject(i);if(game==null)continue;if(!console.equals("All games")&&!(console.equals("Favorites")?game.optBoolean("favorite"):console.equals(game.optString("console"))))continue;if(game.optString("title").toLowerCase(Locale.ROOT).contains(query))visible.add(game);}gridPosition=0;grid.setSelection(0);adapter.notifyDataSetChanged();selected=visible.isEmpty()?null:visible.get(0);details();}
 void setCover(ImageView view,JSONObject game){String cover=game.optString("cover");view.setTag(cover);view.setContentDescription(game.optString("title")+" cover");if(cover.isEmpty())return;android.graphics.Bitmap cached=covers.get(cover);if(cached!=null){view.setImageBitmap(cached);return;}if(requested.add(cover))artwork.submit(()->{try{android.graphics.BitmapFactory.Options opts=new android.graphics.BitmapFactory.Options();opts.inJustDecodeBounds=true;try(java.io.InputStream in=getContentResolver().openInputStream(Uri.parse(cover))){android.graphics.BitmapFactory.decodeStream(in,null,opts);}opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>240||opts.outHeight/opts.inSampleSize>320)opts.inSampleSize*=2;opts.inJustDecodeBounds=false;android.graphics.Bitmap bitmap;try(java.io.InputStream in=getContentResolver().openInputStream(Uri.parse(cover))){bitmap=android.graphics.BitmapFactory.decodeStream(in,null,opts);}if(bitmap!=null)covers.put(cover,bitmap);runOnUiThread(()->{requested.remove(cover);if(!isDestroyed()){if(cover.equals(view.getTag()))view.setImageBitmap(bitmap);View detailArt=detail==null?null:detail.findViewWithTag(cover);if(detailArt instanceof ImageView)((ImageView)detailArt).setImageBitmap(bitmap);updateCoverViews(grid,cover,bitmap);updateCoverViews(detail,cover,bitmap);}});}catch(Exception ignored){runOnUiThread(()->requested.remove(cover));}});}

 void details(){stopGameplay();detail.removeAllViews();if(selected==null){detail.addView(text(games.length()==0?"Your game collection starts here.":"No matching games",23));TextView help=text("Add your Nintendo, Super Nintendo or SEGA GENESIS game files. Select a cover to see details and launch its standalone emulator.\n\nGames and performance have not been verified yet.",15);help.setPadding(0,dp(18),0,0);detail.addView(help);return;}final JSONObject game=selected;ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.FIT_CENTER);art.setBackgroundColor(0xff26324a);FrameLayout media=new FrameLayout(this);media.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);media.setFocusable(false);media.addView(art,new FrameLayout.LayoutParams(-1,-1));detail.addView(media,new LinearLayout.LayoutParams(-1,0,1));setCover(art,game);startGameplay(media,game);TextView title=text(game.optString("title"),21);title.setMaxLines(2);title.setPadding(0,dp(10),0,dp(5));detail.addView(title);TextView meta=text(consoleLabel(game.optString("console"))+(game.optString("year").isEmpty()?"":"  ·  "+game.optString("year")),13);meta.setTextColor(0xff91bdff);detail.addView(meta);TextView description=text(game.optString("description",""),14);description.setMaxLines(5);description.setMaxLines(2);if(!game.optString("description").isEmpty())detail.addView(description);TextView best=text("PERSONAL BEST  "+(game.optString("highScore").isEmpty()?"—":game.optString("highScore")),13);best.setTextColor(TvStyle.AMBER);best.setPadding(0,dp(7),0,dp(8));detail.addView(best);LinearLayout actions=new LinearLayout(this);Button play=TvStyle.button(this,"▶  Play",()->play(game));play.setTextSize(12);actions.addView(play,new LinearLayout.LayoutParams(0,dp(32),0.8f));Button options=TvStyle.button(this,"Game options",()->options(game));options.setTextSize(12);LinearLayout.LayoutParams optionsLp=new LinearLayout.LayoutParams(0,dp(32),1.1f);optionsLp.leftMargin=dp(8);actions.addView(options,optionsLp);Button controllers=TvStyle.button(this,"Controllers",()->controllers());controllers.setTextSize(12);LinearLayout.LayoutParams controllerLp=new LinearLayout.LayoutParams(0,dp(32),1f);controllerLp.leftMargin=dp(8);actions.addView(controllers,controllerLp);detail.addView(actions);gamePlay=play;gameOptions=options;gameControllers=controllers;wireActionNavigation();}
 void updateCoverViews(View view,String cover,android.graphics.Bitmap bitmap){if(view==null)return;if(view instanceof ImageView&&cover.equals(view.getTag()))((ImageView)view).setImageBitmap(bitmap);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)updateCoverViews(group.getChildAt(i),cover,bitmap);}}
 boolean direction(int key){return key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT;}
 boolean navigationDown(KeyEvent e){if(e.getAction()!=KeyEvent.ACTION_DOWN)return false;long now=android.os.SystemClock.uptimeMillis();if(e.getRepeatCount()>0&&now-lastNavigation<160)return false;lastNavigation=now;return true;}
 void focusGameGrid(){if(visible.isEmpty())return;gridPosition=Math.max(0,Math.min(gridPosition,visible.size()-1));grid.requestFocus();grid.setSelection(gridPosition);}
 void wireGameNavigation(){for(int n=0;n<consoleButtons.size();n++){final int index=n;consoleButtons.get(n).setOnKeyListener((v,key,e)->{if(!direction(key))return false;if(navigationDown(e)){if(key==KeyEvent.KEYCODE_DPAD_RIGHT)focusGameGrid();else if(key==KeyEvent.KEYCODE_DPAD_UP)consoleButtons.get(Math.max(0,index-1)).requestFocus();else if(key==KeyEvent.KEYCODE_DPAD_DOWN)consoleButtons.get(Math.min(consoleButtons.size()-1,index+1)).requestFocus();}return true;});}grid.setOnKeyListener((v,key,e)->{if(!direction(key))return false;if(navigationDown(e)&&!visible.isEmpty()){int at=grid.getSelectedItemPosition();if(at<0)at=gridPosition;int next=at;if(key==KeyEvent.KEYCODE_DPAD_UP&&at>=3)next=at-3;else if(key==KeyEvent.KEYCODE_DPAD_DOWN&&at+3<visible.size())next=at+3;else if(key==KeyEvent.KEYCODE_DPAD_LEFT){if(at%3==0){int rail=Math.max(0,Arrays.asList(new String[]{"All games","NES","SNES","Mega Drive / Genesis"}).indexOf(console));consoleButtons.get(rail).requestFocus();return true;}next=at-1;}else if(key==KeyEvent.KEYCODE_DPAD_RIGHT){if(at%3==2||at+1>=visible.size()){if(gamePlay!=null)gamePlay.requestFocus();return true;}next=at+1;}gridPosition=next;grid.setSelection(next);}return true;});}
 void wireActionNavigation(){Button[] buttons={gamePlay,gameOptions,gameControllers};for(int n=0;n<buttons.length;n++){final int index=n;buttons[n].setOnKeyListener((v,key,e)->{if(!direction(key))return false;if(navigationDown(e)){if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_LEFT&&index==0)focusGameGrid();else if(key==KeyEvent.KEYCODE_DPAD_LEFT)buttons[index-1].requestFocus();else if(key==KeyEvent.KEYCODE_DPAD_RIGHT)buttons[Math.min(buttons.length-1,index+1)].requestFocus();}return true;});}}
 void controllers(){new AlertDialog.Builder(this).setTitle("Controllers").setItems(new String[]{"Pair / manage Bluetooth controller","Map controller buttons"},(d,index)->{if(index==0)pairController();else chooseMapping();}).setNegativeButton("Close",null).show();}
 void pairController(){String[] actions={"android.settings.BLUETOOTH_SETTINGS","android.settings.SETTINGS"};for(String action:actions)try{startActivity(new Intent(action));return;}catch(ActivityNotFoundException ignored){}Toast.makeText(this,"Open Android Settings to pair your controller",Toast.LENGTH_LONG).show();}
 void chooseMapping(){new AlertDialog.Builder(this).setTitle("Map controller for").setItems(DISPLAY_NAMES,(d,index)->new AlertDialog.Builder(this).setTitle(DISPLAY_NAMES[index]+" controller mapping").setMessage("Button mappings are saved separately for each console. In the emulator, open Key/Gamepad Input Setup, choose your controller, then assign its buttons. Set a Menu / Exit shortcut so you can return to Games.").setPositiveButton("Open emulator",(a,b)->{Intent launch=getPackageManager().getLaunchIntentForPackage(PACKAGES[index]);if(launch==null)launch=getPackageManager().getLeanbackLaunchIntentForPackage(PACKAGES[index]);if(launch!=null)try{startActivity(launch);return;}catch(ActivityNotFoundException ignored){}new AlertDialog.Builder(this).setTitle("Emulator setup needed").setMessage("The standalone emulator for "+DISPLAY_NAMES[index]+" is not installed yet. Controller pairing is available now; button mapping will be available after emulator setup.").setPositiveButton("OK",null).show();}).setNegativeButton("Cancel",null).show()).setNegativeButton("Cancel",null).show();}
 void pickGameplay(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("video/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,33);}
 void stopGameplay(){previewSerial++;previewHandler.removeCallbacksAndMessages(null);if(gameplay!=null){gameplay.setOnPreparedListener(null);gameplay.setOnErrorListener(null);gameplay.stopPlayback();android.view.ViewParent holder=gameplay.getParent();if(holder instanceof ViewGroup){ViewGroup panel=(ViewGroup)holder;panel.removeView(gameplay);for(int i=0;i<panel.getChildCount();i++)if(panel.getChildAt(i) instanceof ImageView)panel.getChildAt(i).setVisibility(View.VISIBLE);}gameplay=null;}previewGameId="";}
 void startGameplay(FrameLayout media,JSONObject game){String address=game.optString("preview");if(address.isEmpty()||previewPaused)return;int ticket=++previewSerial;previewGameId=game.optString("id");previewHandler.postDelayed(()->{if(previewPaused||ticket!=previewSerial)return;VideoView video=new PassivePreviewVideo(this);gameplay=video;video.setAudioFocusRequest(android.media.AudioManager.AUDIOFOCUS_NONE);video.setFocusable(false);video.setFocusableInTouchMode(false);View poster=media.getChildAt(0);media.addView(video,0,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));video.setOnPreparedListener(mp->{if(previewPaused||ticket!=previewSerial){video.stopPlayback();return;}mp.setVolume(0,0);mp.setLooping(true);poster.setVisibility(View.INVISIBLE);video.setVisibility(View.VISIBLE);video.start();});video.setOnErrorListener((mp,w,e)->{poster.setVisibility(View.VISIBLE);video.setVisibility(View.INVISIBLE);video.stopPlayback();return true;});try{video.setVideoURI(Uri.parse(address));}catch(Exception ignored){video.setVisibility(View.INVISIBLE);}},700);}
 protected void onPause(){if(retroAds!=null)retroAds.setRunning(false);previewPaused=true;stopGameplay();super.onPause();}
 protected void onResume(){super.onResume();previewPaused=false;if(retroAds!=null)retroAds.setRunning(true);if(detail!=null&&detail.getChildCount()>0&&detail.getChildAt(0) instanceof FrameLayout&&selected!=null){stopGameplay();startGameplay((FrameLayout)detail.getChildAt(0),selected);}}
 void pick(boolean artwork){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(artwork?"image/*":"*/*");if(!artwork)intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,artwork?32:31);}
 String fileName(Uri uri){try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())return cursor.getString(0);}catch(Exception ignored){}return "Game";}
 void remember(Uri uri,Intent data){try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==33&&selected!=null&&data.getData()!=null){remember(data.getData(),data);try{selected.put("preview",data.getData().toString());selected.remove("previewDisabled");save();details();}catch(Exception ignored){}return;}if(request==32&&selected!=null&&data.getData()!=null){remember(data.getData(),data);try{selected.put("cover",data.getData().toString());save();filter();}catch(Exception ignored){}return;}if(request==31){ArrayList<Uri> files=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)files.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)files.add(data.getData());for(Uri uri:files){remember(uri,data);String name=fileName(uri),lower=name.toLowerCase(Locale.ROOT);int system=lower.endsWith(".nes")?0:lower.endsWith(".smc")||lower.endsWith(".sfc")?1:lower.endsWith(".md")||lower.endsWith(".gen")?2:-1;if(system>=0)addGame(uri,name,system);else new AlertDialog.Builder(this).setTitle("Console for "+name).setItems(DISPLAY_NAMES,(d,index)->addGame(uri,name,index)).setNegativeButton("Skip",null).show();}filter();}}
 void addGame(Uri uri,String name,int system){try{for(int i=0;i<games.length();i++)if(uri.toString().equals(games.getJSONObject(i).optString("uri")))return;JSONObject game=new JSONObject();game.put("id",UUID.randomUUID().toString());game.put("title",name.replaceFirst("\\.[^.]+$",""));game.put("console",CONSOLES[system]);game.put("uri",uri.toString());games.put(game);save();filter();}catch(Exception e){Toast.makeText(this,"Could not add game",1).show();}}
 void play(JSONObject game){int system=Arrays.asList(CONSOLES).indexOf(game.optString("console"));if(system<0)return;String target=PACKAGES[system];Uri uri=Uri.parse(game.optString("uri"));try{Intent launch=new Intent(Intent.ACTION_VIEW).setData(uri).setPackage(target).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);launch.setClipData(ClipData.newRawUri("Game",uri));grantUriPermission(target,uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(launch);}catch(ActivityNotFoundException e){new AlertDialog.Builder(this).setTitle("Emulator setup needed").setMessage("The standalone emulator for "+DISPLAY_NAMES[system]+" is not installed or could not accept this file. Your library entry is saved.").setPositiveButton("OK",null).show();}catch(Exception e){Toast.makeText(this,"Game file unavailable. Reconnect its storage or add it again.",1).show();}}
 void options(JSONObject game){new AlertDialog.Builder(this).setTitle(game.optString("title")).setItems(new String[]{"Edit details","Choose cover image","Choose gameplay video","Remove gameplay video","Remove from library"},(d,index)->{selected=game;if(index==1)pick(true);else if(index==0)edit(game);else if(index==2)pickGameplay();else if(index==3){game.remove("preview");try{game.put("previewDisabled",true);}catch(JSONException ignored){}save();details();}else new AlertDialog.Builder(this).setMessage("Remove this library entry? The game file will stay on its storage.").setPositiveButton("Remove",(a,b)->{JSONArray next=new JSONArray();for(int i=0;i<games.length();i++){JSONObject item=games.optJSONObject(i);if(item!=null&&!item.optString("id").equals(game.optString("id")))next.put(item);}games=next;save();filter();}).setNegativeButton("Cancel",null).show();}).show();}
 protected void onDestroy(){stopGameplay();artwork.shutdownNow();covers.evictAll();super.onDestroy();}
 void edit(JSONObject game){LinearLayout form=new LinearLayout(this);form.setOrientation(1);ArrayList<EditText> fields=new ArrayList<>();String[] keys={"title","year","description","highScore"};for(String key:keys){EditText field=new EditText(this);field.setText(game.optString(key));field.setHint(key.equals("highScore")?"Personal best score (entered manually)":key);form.addView(field);fields.add(field);}new AlertDialog.Builder(this).setTitle("Game details").setView(form).setPositiveButton("Save",(d,w)->{try{for(int i=0;i<keys.length;i++)game.put(keys[i],fields.get(i).getText().toString().trim());save();filter();}catch(Exception ignored){}}).setNegativeButton("Cancel",null).show();}
